import { useEffect, useState, useRef, useCallback } from 'react'
import { Error } from '../../../../commonStyle/index.style'
import { MINI_INFO } from '../../../../images'
import { CustomText } from '../../../../components'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { InputStyles, StyleInput, Label } from './index.style'

function InputV2({
  placeholder,
  backgroundColor,
  error,
  subText,
  className,
  name,
  displayBorder,
  defaultValue,
  opacity,
  title,
  maxlength,
  required,
  type,
  onChange,
  disabled = false,
  textArea = false,
  onlyLetters = false,
  ...props
}) {
  const [showLabel, setShowLabel] = useState(false)
  const [value, setValue] = useState(defaultValue || '')
  const ref = useRef(null)

  useEffect(() => {
    const el = document.getElementById(name)
    if (el) {
      el.addEventListener('focusin', (e) => {
        e.preventDefault()
        e.stopPropagation()
      })
    }
  }, [name])

  useEffect(() => {
    setValue(defaultValue || '')
  }, [defaultValue])

  const onClickHandler = (e) => {
    setShowLabel(true)
  }

  const handleClickOutside = useCallback(
    (event) => {
      if (ref.current && !ref.current.contains(event.target)) {
        if (!value) {
          setShowLabel(false)
        }
      }
    },
    [value]
  )

  const handleChange = (e) => {
    const newValue = e.target.value
    if (onlyLetters) {
      const lettersOnly = newValue.replace(/[^a-zA-Z]/g, '')
      e.target.value = lettersOnly
      setValue(lettersOnly)
    } else {
      setValue(newValue)
    }
    if (onChange) {
      onChange(e)
    }
  }

  useEffect(() => {
    document.addEventListener('click', handleClickOutside, false)

    return () => {
      document.removeEventListener('click', handleClickOutside, false)
    }
  }, [handleClickOutside])

  return (
    <InputStyles
      className={className}
      backgroundColor={backgroundColor}
      displayBorder={displayBorder}
      opacity={opacity}
      id={name}
      ref={ref}
      disabled={disabled}
      bottom={props.bottom}
      error={!!error}
    >
      <Label active={showLabel || value} disabled={disabled}>
        {title}
      </Label>
      <StyleInput
        as={textArea ? 'textarea' : 'input'}
        rows={textArea ? 1 : undefined}
        onClick={onClickHandler}
        defaultValue={defaultValue || value}
        onChange={handleChange}
        disabled={disabled}
        error={!!error}
        {...props}
        maxLength={maxlength}
        autoComplete={props.autocomplete || 'chrome-off'}
        data-form-type="other"
        data-lpignore="true"
      />
      {subText && (
        <CustomText
          color={AgentColorPallette.fontGrey}
          size="0.7em"
          top="0.4rem"
          marginBottom="5px"
          className="display-flex flex-start"
        >
          <img src={MINI_INFO} alt="Info" />
          &nbsp;&nbsp;<span>{subText}</span>
        </CustomText>
      )}
      {error && <Error>{error}</Error>}
    </InputStyles>
  )
}

export default InputV2
