import {
  useResetError,
  useErrorContextValue,
  useLoaderContextValue,
} from '@pasarpolis/common-react-hooks'
import { get } from 'lodash'
import moment from 'moment'
import { useEffect, useCallback, useRef, useState, useMemo } from 'react'
import { useHistory } from 'react-router'
import {
  BottomActionContainerStyle,
  DisplayCircleIcon,
  DisplayFlexRCC,
} from '../../../../../commonStyle/index.style'
import { Button, Container, CustomText } from '../../../../../components'
import ConfirmationModalV2 from '../../../../../components/ConfirmationModalV2'
import DynamicForm from '../../../../../components/DynamicForm'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { PolicyContextProvider } from '../../context'
import {
  useCreateEndorsementReq,
  useGetEndorsementReqForm,
  useGetPolicyDetails,
} from '../../state/hooks/usePolicyState'
import { CreateEndorsementStyle } from './index.style'
import { ErrorBoundaryStyle } from '../../../../../components/ErrorBoundary/index.style'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { GOLD_TRANSACTION, INFORMATION_SENT } from '../../../../../images'
import { OfflinePaymentStyle } from '../../../InstantPayout/Pages/OfflinePaymentConfirmation/container/index.style'
import ButtonWithIcon from '../../../../../components/ButtonWithIcon'
import { useWindowSize } from '../../../../../helpers/hooks'
import { INPUT_FILE_TYPE } from '../../../../../constants/file'

const CreateEndorsementContainer = (props) => {
  const { match, location } = props
  const history = useHistory()
  const policyId = get(match, 'params.policyId', '') || get(location, 'state.id', '')

  const navigateToTransactionDetail = useCallback(() => {
    history.push(`/transactions/${policyId}/details`)
  }, [history, policyId])

  const [{ getPolicyDetailData }, getPolicyDetailRequest] = useGetPolicyDetails()
  const [{ getEndorsementReqFormData }, getEndorsementReqFormRequest] = useGetEndorsementReqForm()
  const [, createEndorsementReqRequest] = useCreateEndorsementReq()
  const [
    { GET_POLICY_DETAIL_LOADER, GET_ENDORSEMENT_REQ_FORM_LOADER, CREATE_ENDORSEMENT_REQ_LOADER },
  ] = useLoaderContextValue()
  const [
    {
      GET_POLICY_DETAIL_ERROR,
      getPolicyDetailStatus,
      getEndorsementReqFormStatus,
      createEndorsementReqStatus,
    },
  ] = useErrorContextValue()
  const { resetError } = useResetError()
  const [isOther, setIsOther] = useState(false)
  const [endorsementReasons, setEndorsementReasons] = useState([])
  const that = useRef({})
  const formRef = useRef({})
  const currentPayload = useRef({})
  const [confirmationOpen, setConfirmationOpen] = useState(false)
  const [currentError, setCurrentError] = useState('')
  const [showSuccess, setShowSuccess] = useState(false)
  const { height } = useWindowSize()

  // Helper function to get string value from reason (handles different data structures)
  const getReasonString = (reason) => {
    if (typeof reason === 'string') return reason
    if (reason && typeof reason === 'object') {
      return reason.label || reason.value || reason.title || reason.name || ''
    }
    return ''
  }

  // Calculate if upload field should be required, optional, or hidden
  const uploadFieldConfig = useMemo(() => {
    // If no reasons selected: hide field
    if (
      !endorsementReasons ||
      !Array.isArray(endorsementReasons) ||
      endorsementReasons.length === 0
    ) {
      return { required: false, showField: false }
    }

    // Convert all reasons to strings for comparison
    const reasonStrings = endorsementReasons.map(getReasonString).map((r) => r.toLowerCase())

    // Define endorsement types that require mandatory documents
    const mandatoryTypes = [
      'perubahan nama tertanggung',
      'perubahan nomor plat',
      'perubahan alamat tertanggung dan risk location',
      'penambahan / pengurangan tsi',
    ]

    // Check if any selected reason requires mandatory documents
    const hasMandatory = mandatoryTypes.some((type) =>
      reasonStrings.some((reasonStr) => reasonStr.includes(type) || type.includes(reasonStr))
    )

    // Check if "Lainnya" is selected
    const hasLainnya = reasonStrings.some(
      (reasonStr) => reasonStr.includes('lainnya') || reasonStr === 'lainnya'
    )

    // If has mandatory types: show field, required
    if (hasMandatory) {
      return { required: true, showField: true }
    }

    // If only has "Lainnya" and no mandatory: show field, optional
    if (hasLainnya && !hasMandatory) {
      return { required: false, showField: true }
    }

    // For types that don't require documents: hide field
    return { required: false, showField: false }
  }, [endorsementReasons])

  useEffect(() => {
    getPolicyDetailRequest({
      policyId,
    })
  }, [policyId, getPolicyDetailRequest])

  useEffect(() => {
    if (GET_POLICY_DETAIL_ERROR) {
      setCurrentError(getPolicyDetailStatus)
      resetError(['GET_POLICY_DETAIL_ERROR', 'getPolicyDetailStatus'])
    } else if (getPolicyDetailData) {
      if (getPolicyDetailData.policy_status) {
        if (
          ['ACTIVE', 'PROVISIONAL_ISSUED'].includes(getPolicyDetailData.policy_status) &&
          !getPolicyDetailData.expired
        ) {
          getEndorsementReqFormRequest()
          setCurrentError('')
        } else {
          setCurrentError(LANG_STRINGS.policyStatusInvalid)
        }
        resetError(['GET_POLICY_DETAIL_ERROR', 'getPolicyDetailStatus'])
      }
    }
  }, [
    getEndorsementReqFormRequest,
    getPolicyDetailData,
    getPolicyDetailStatus,
    GET_POLICY_DETAIL_ERROR,
    resetError,
  ])

  useEffect(() => {
    if (getEndorsementReqFormStatus) {
      if (getEndorsementReqFormStatus === 'success') {
        setCurrentError('')
      } else {
        setCurrentError(LANG_STRINGS.failedGetForm)
      }
    }
  }, [getEndorsementReqFormStatus])

  useEffect(() => {
    if (createEndorsementReqStatus) {
      if (createEndorsementReqStatus === 'success') {
        setShowSuccess(true)
        resetError(['createEndorsementReqStatus'])
      } else {
        ShowSnackbar.error({
          visible: true,
          text: createEndorsementReqStatus,
        })
        resetError(['createEndorsementReqStatus'])
      }
    }
  }, [createEndorsementReqStatus, resetError])

  const getForm = useCallback(() => {
    // type, name, title, data, required, defaultValue, disabled
    const other = isOther
      ? [
          {
            name: 'other_desc',
            type: 'textarea',
            title: 'Lainnya',
            regex_validation: /^.{20,300}$/,
            errormsg: LANG_STRINGS.otherLengthErrorMsg,
            data: {
              className: 'endorsement-text-area',
              rows: 3,
            },
          },
        ]
      : []
    if (!isOther) {
      if (formRef.current?.resetFormField) {
        formRef.current.resetFormField('other_desc', '')
      }
    }

    const uploadField = uploadFieldConfig.showField
      ? [
          {
            name: 'endorsement_upload',
            type: 'uploadFile',
            title: LANG_STRINGS.endorsementUpload,
            required: uploadFieldConfig.required,
            data: {
              isMultiple: true,
              maxUpload: 10, // Optional: limit the number of files (adjust as needed)
              fileType: `${INPUT_FILE_TYPE.IMAGE},${INPUT_FILE_TYPE.PDF}`,
            },
          },
        ]
      : []

    const form = [
      {
        name: 'endorsement_changes',
        type: 'textarea',
        title: LANG_STRINGS.endorsementRequirements,
        required: true,
        data: {
          className: 'endorsement-text-area',
          rows: 5,
        },
      },
      {
        name: 'effective_date',
        type: 'datePicker',
        title: LANG_STRINGS.effectiveDate,
        required: true,
      },
      {
        name: 'endorsement_reason',
        type: 'multiple_select',
        title: LANG_STRINGS.endorsementReason,
        required: true,
        data: {
          data: [...get(getEndorsementReqFormData, 'endorsement_reason.data', [])],
          showChips: true,
        },
      },
      ...other,
      ...uploadField,
    ]
    return form
  }, [getEndorsementReqFormData, isOther, uploadFieldConfig])

  const handleChange = useCallback(
    (data) => {
      that.current = {
        ...that.current,
        ...data,
      }
      const endorsementReason = get(that.current, 'endorsement_reason', [])

      // Update endorsement reasons state for upload field logic
      if (data.endorsement_reason !== undefined) {
        const reasons = Array.isArray(data.endorsement_reason)
          ? data.endorsement_reason
          : [data.endorsement_reason]
        setEndorsementReasons(reasons)
      }

      // Helper to check if reason matches "Lainnya"
      const checkLainnya = (reason) => {
        const reasonStr =
          typeof reason === 'string'
            ? reason
            : reason?.label || reason?.value || reason?.title || ''
        return reasonStr.toLowerCase().includes('lainnya') || reasonStr === 'Lainnya'
      }

      // Check if "Lainnya" is selected
      const hasLainnya = Array.isArray(endorsementReason)
        ? endorsementReason.some(checkLainnya)
        : checkLainnya(endorsementReason)

      if (hasLainnya) {
        setIsOther(true)
      } else {
        setIsOther(false)
        // Reset other_desc field if "Lainnya" is deselected
        if (formRef.current?.resetFormField) {
          formRef.current.resetFormField('other_desc', '')
        }
      }
    },
    [setIsOther]
  )

  // Reset upload field when endorsement reasons change and upload is not required
  useEffect(() => {
    if (!uploadFieldConfig.showField && formRef.current?.resetFormField) {
      formRef.current.resetFormField('endorsement_upload', '')
    }
  }, [uploadFieldConfig])

  const handleSubmit = useCallback(() => {
    // submit the Endorsement Request
    const data = formRef.current.validateFormValues()
    if (data) {
      const {
        effective_date: effectiveDate,
        other_desc: otherDesc,
        endorsement_reason: endorsementReason,
        endorsement_changes: endorsementChanges,
        endorsement_upload: endorsementUpload,
      } = data
      if (!effectiveDate || !endorsementChanges || !endorsementReason) return
      if (Array.isArray(endorsementReason)) {
        if (!endorsementReason.length) return
      } else return
      if (isOther) {
        if (otherDesc === LANG_STRINGS.otherLengthErrorMsg) return
        if (!otherDesc.length) return
      }

      // Validate endorsement upload based on requirements
      if (uploadFieldConfig.showField && uploadFieldConfig.required) {
        // Upload is mandatory for selected endorsement types
        if (!endorsementUpload) return
        if (Array.isArray(endorsementUpload)) {
          if (!endorsementUpload.length) return
        }
      }

      // Extract URLs from upload data (handles both single and multiple uploads)
      // When isMultiple is true, endorsementUpload will be an array of objects with url property
      const uploadUrls = endorsementUpload
        ? Array.isArray(endorsementUpload)
          ? endorsementUpload.map((file) => file.url || file)
          : [endorsementUpload.url || endorsementUpload]
        : []

      const payload = {
        body: {
          endorsement_changes: endorsementChanges,
          endorsement_reason: endorsementReason,
          effective_date: moment(effectiveDate).format('YYYY-MM-DD'),
          insurance: policyId,
          ...(uploadUrls.length > 0 ? { endorsement_upload: uploadUrls } : {}),
          ...(isOther ? { other_desc: otherDesc } : {}),
        },
      }
      currentPayload.current = payload
      setConfirmationOpen(true)
    }
  }, [policyId, isOther, uploadFieldConfig])

  const handleErrorFunc = useCallback(() => {
    switch (currentError) {
      case LANG_STRINGS.notFound:
        return [() => history.push('/dashboard'), LANG_STRINGS.goToDashboard]
      case LANG_STRINGS.policyStatusInvalid:
        return [navigateToTransactionDetail, LANG_STRINGS.goToTransactonDetail]
      default:
        return [() => window.location.reload(), LANG_STRINGS.reloadPage]
    }
  }, [currentError, history, navigateToTransactionDetail])

  return (
    <Container
      title={showSuccess ? LANG_STRINGS.endorsementReqSentConfirm : LANG_STRINGS.createEndorsement}
      loader={
        GET_ENDORSEMENT_REQ_FORM_LOADER || CREATE_ENDORSEMENT_REQ_LOADER || GET_POLICY_DETAIL_LOADER
      }
      hideBottomTabs={!showSuccess}
      displayBackButton={!(!!currentError || showSuccess)}
    >
      {currentError ? (
        <ErrorBoundaryStyle>
          <div className="error-text">
            <i className="fas fa-exclamation-triangle warning-error" />
            <br />
            {currentError === LANG_STRINGS.notFound ? LANG_STRINGS.policyNotFound : currentError}
          </div>
          <Button className="reload-btn" onClick={handleErrorFunc()[0]}>
            {handleErrorFunc()[1]}
          </Button>
        </ErrorBoundaryStyle>
      ) : showSuccess ? (
        <OfflinePaymentStyle>
          <DisplayFlexRCC>
            <DisplayCircleIcon
              width="190px"
              height="190px"
              bgColor={AgentColorPallette.fontLightGrey}
              className="photo-confirmation"
            >
              <img src={INFORMATION_SENT} width="70%" height="auto" alt="" />
            </DisplayCircleIcon>
          </DisplayFlexRCC>
          <CustomText
            color={AgentColorPallette.black}
            size="15px"
            bottom="4px"
            top="10px"
            weight={800}
            textAlign="center"
          >
            {LANG_STRINGS.endorsementReqRequestSuccess}
          </CustomText>
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size="14px"
            bottom="10px"
            textAlign="center"
          >
            {LANG_STRINGS.endorsementReqRequestSuccessContent}
          </CustomText>
          <div className="btn-container">
            <ButtonWithIcon
              text={LANG_STRINGS.endorsementReqSuccessButton}
              icon={GOLD_TRANSACTION}
              className="icon-filter"
              iconRight
              onClick={navigateToTransactionDetail}
            />
          </div>
        </OfflinePaymentStyle>
      ) : (
        <BottomActionContainerStyle direction="column" align="stretch" padding="0">
          <CreateEndorsementStyle innerHeight={height}>
            <DynamicForm
              formName="endorsementRequestForm"
              form={getForm()}
              ref={formRef}
              onChange={handleChange}
            />
            <div className="action-remark">
              Remark: <span>{LANG_STRINGS.endorsementRemark}</span>
            </div>
            <Button color={AgentColorPallette.darkCharcoal} onClick={handleSubmit}>
              {LANG_STRINGS.applyEndorsement}
            </Button>
            <ConfirmationModalV2
              okText={LANG_STRINGS.agree}
              cancelText={LANG_STRINGS.no}
              title={LANG_STRINGS.applyEndorsement}
              cancelButtonColor={AgentColorPallette.goldenText}
              okButtonColor={AgentColorPallette.goldenText}
              onCancel={() => {
                currentPayload.current = {}
                setConfirmationOpen(false)
              }}
              onOk={() => {
                createEndorsementReqRequest(currentPayload.current)
                setConfirmationOpen(false)
              }}
              visible={confirmationOpen}
            >
              <CustomText size="1.2em" color={AgentColorPallette.darkCharcoal} bottom="1.5rem">
                {LANG_STRINGS.endorsementReqConfirmContent}
              </CustomText>
            </ConfirmationModalV2>
          </CreateEndorsementStyle>
        </BottomActionContainerStyle>
      )}
    </Container>
  )
}

function CreateEndorsement(props) {
  return (
    <PolicyContextProvider>
      <CreateEndorsementContainer {...props} />
    </PolicyContextProvider>
  )
}

export default CreateEndorsement
