import { useEffect, useRef, useState } from 'react'
import { Input as StyledInput, Label, InputWrapper } from './index.style'
import { Error } from '../../../../commonStyle/index.style'

function InputNumberV2(props) {
  const {
    className,
    placeholder,
    error,
    onChange,
    onClick,
    disabled,
    value,
    type,
    top,
    bottom,
    prefix,
    autocomplete,
  } = props

  const [showLabel, setShowLabel] = useState(false)
  const [inputValue, setInputValue] = useState(value || '')

  const ref = useRef(null)

  useEffect(() => {
    setInputValue(value || '')
  }, [value])

  const onClickHandler = (e) => {
    setShowLabel(true)
    onClick && onClick()
  }

  const onChangeHandler = ({ value }) => {
    setInputValue(Number(value))
    onChange && onChange({ value })
  }

  const handleClickOutside = (event) => {
    if (ref.current && !ref.current.contains(event.target)) {
      if (!inputValue) {
        setShowLabel(false)
      }
    }
  }

  useEffect(() => {
    document.addEventListener('click', handleClickOutside, false)

    return () => {
      document.removeEventListener('click', handleClickOutside, false)
    }
  }, [inputValue])

  return (
    <InputWrapper ref={ref} top={top} bottom={bottom} error={!!error} className={className}>
      <Label active={showLabel || inputValue}>{placeholder}</Label>
      {type === 'amount' && (
        <StyledInput
          onClick={onClickHandler}
          thousandSeparator="."
          decimalSeparator=","
          prefix="Rp "
          value={inputValue}
          disabled={disabled}
          onValueChange={onChangeHandler}
          decimalScale={0}
          allowNegative={false}
          className=""
          error={!!error}
          autoComplete={autocomplete || 'chrome-off'}
          data-form-type="other"
          data-lpignore="true"
        />
      )}
      {type === 'percentage' && (
        <StyledInput
          onClick={onClickHandler}
          thousandSeparator="."
          decimalSeparator=","
          suffix=" %"
          value={inputValue}
          disabled={disabled}
          onValueChange={onChangeHandler}
          decimalScale={2}
          allowNegative={false}
          className=""
          error={!!error}
          autoComplete={autocomplete || 'chrome-off'}
          data-form-type="other"
          data-lpignore="true"
        />
      )}
      {!type && (
        <StyledInput
          onClick={onClickHandler}
          value={inputValue}
          disabled={disabled}
          onValueChange={onChangeHandler}
          decimalScale={0}
          className=""
          error={!!error}
          {...(prefix ? { prefix: '+62' } : {})}
          autoComplete={autocomplete || 'chrome-off'}
          data-form-type="other"
          data-lpignore="true"
        />
      )}
      {error && <Error>{error}</Error>}
    </InputWrapper>
  )
}

export default InputNumberV2
